// Work MVP 메인 페이지
import { useState, useMemo, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useProjects, useTasks, useProjectTodos, useScheduleEvents, useScheduleTodos } from '../hooks/useWorkStore';
import type { ViewMode, SortMode, Project, ProjectTask, ProjectTodo } from '../types/work';
import ProjectList from '../components/work/ProjectList';
import ProjectModal from '../components/work/ProjectModal';
import TaskList from '../components/work/TaskList';
import TaskModal from '../components/work/TaskModal';
import TodoList from '../components/work/TodoList';
import TodoModal from '../components/work/TodoModal';
import { ProjectsTimeline, TasksTimeline, TodosTimeline } from '../components/work/WorkTimeline';
import FilterDropdown from '../components/FilterDropdown';
import EventModal from '../components/EventModal';
import type { ScheduleEvent } from '../types';
import '../styles/WorkPage.css';

// 마감일 필터 옵션
const DUE_DATE_OPTIONS = [
  { id: 'overdue', label: '지남' },
  { id: 'today', label: '오늘' },
  { id: 'this_week', label: '이번 주' },
  { id: 'this_month', label: '이번 달' },
  { id: 'no_due', label: '마감일 없음' },
];

type WorkTab = 'projects' | 'tasks' | 'todos';

// localStorage 키
const WORK_STATE_KEY = 'myschedul_work_state';

// 저장된 상태 로드
function loadWorkState(): { tab: WorkTab; view: ViewMode } {
  try {
    const saved = localStorage.getItem(WORK_STATE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      return {
        tab: ['projects', 'tasks', 'todos'].includes(parsed.tab) ? parsed.tab : 'projects',
        view: ['list', 'timeline'].includes(parsed.view) ? parsed.view : 'list',
      };
    }
  } catch (e) {
    console.error('Failed to load work state:', e);
  }
  return { tab: 'projects', view: 'list' };
}

// 상태 저장
function saveWorkState(tab: WorkTab, view: ViewMode) {
  try {
    localStorage.setItem(WORK_STATE_KEY, JSON.stringify({ tab, view }));
  } catch (e) {
    console.error('Failed to save work state:', e);
  }
}

export default function WorkPage() {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const { signOut, user } = useAuth();
  
  // URL 쿼리 파라미터 또는 localStorage에서 상태 읽기
  const tabFromUrl = searchParams.get('tab') as WorkTab | null;
  const viewFromUrl = searchParams.get('view') as ViewMode | null;
  
  // 초기 상태 결정: URL > localStorage > 기본값
  const savedState = loadWorkState();
  
  const [activeTab, setActiveTab] = useState<WorkTab>(
    tabFromUrl && ['projects', 'tasks', 'todos'].includes(tabFromUrl) 
      ? tabFromUrl 
      : savedState.tab
  );
  const [viewMode, setViewMode] = useState<ViewMode>(
    viewFromUrl && ['list', 'timeline'].includes(viewFromUrl) 
      ? viewFromUrl 
      : savedState.view
  );
  const [sortMode, setSortMode] = useState<SortMode>('priority');
  const [showCompleted, setShowCompleted] = useState(false);
  const [projectFilter, setProjectFilter] = useState<string[]>([]);
  const [dueDateFilter, setDueDateFilter] = useState<string[]>([]);

  // 상태가 변경될 때 URL 및 localStorage 업데이트
  useEffect(() => {
    const newParams = new URLSearchParams();
    newParams.set('tab', activeTab);
    newParams.set('view', viewMode);
    setSearchParams(newParams, { replace: true });
    
    // localStorage에도 저장
    saveWorkState(activeTab, viewMode);
  }, [activeTab, viewMode, setSearchParams]);
  
  // Projects 탭 상태
  const {
    projects,
    archivedProjects,
    isLoading: isLoadingProjects,
    createProject,
    updateProject,
    archiveProject,
    deleteProjectForever,
    reorderProjects,
  } = useProjects();

  // 프로젝트 완료 취소 (아카이브 해제)
  const handleUnarchiveProject = async (project: Project) => {
    await updateProject({
      ...project,
      status: 'ACTIVE',
      archived_at: null,
      updated_at: Date.now(),
    });
  };
  
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [editingProject, setEditingProject] = useState<Project | null>(null);

  // Tasks 탭 상태
  const {
    tasks,
    doneTasks,
    isLoading: isLoadingTasks,
    createTask,
    updateTask,
    completeTask,
    undoCompleteTask,
    deleteTask,
    reorderTasks,
  } = useTasks();

  const [selectedTask, setSelectedTask] = useState<ProjectTask | null>(null);
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<ProjectTask | null>(null);
  const [taskModalProjectId, setTaskModalProjectId] = useState<string | null>(null);

  // Todos 탭 상태
  const {
    todos,
    doneTodos,
    isLoading: isLoadingTodos,
    createTodo,
    updateTodo,
    completeTodo,
    undoCompleteTodo,
    deleteTodo,
    reorderTodos,
  } = useProjectTodos();

  const [selectedTodo, setSelectedTodo] = useState<ProjectTodo | null>(null);
  const [isTodoModalOpen, setIsTodoModalOpen] = useState(false);
  const [todoModalTaskId, setTodoModalTaskId] = useState<string | null>(null);

  // 일정 이벤트 편집용 상태
  const [selectedScheduleEvent, setSelectedScheduleEvent] = useState<ScheduleEvent | null>(null);
  const [isEventModalOpen, setIsEventModalOpen] = useState(false);

  // 기존 일정 데이터 (읽기 전용 통합)
  const { 
    events: scheduleEvents, 
    isLoading: isLoadingSchedule,
    updateEvent: updateScheduleEvent,
    deleteEvent: deleteScheduleEvent,
  } = useScheduleEvents();

  const {
    activeTodoViews: scheduleTodoViews,
    doneTodoViews: scheduleDoneTodoViews,
    isLoading: isLoadingScheduleTodos,
    deleteTodo: deleteScheduleTodo,
  } = useScheduleTodos();

  // 프로젝트 필터 옵션
  const projectFilterOptions = useMemo(() => {
    const options = projects.map((p) => ({
      id: p.id,
      label: p.title,
      color: p.color,
    }));
    options.unshift({ id: 'none', label: '프로젝트 없음', color: '#6b7280' });
    return options;
  }, [projects]);

  // 마감일 필터 함수
  const matchesDueDateFilter = (dueAt: string | null): boolean => {
    if (dueDateFilter.length === 0) return true;
    
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const endOfWeek = new Date(today);
    endOfWeek.setDate(today.getDate() + (7 - today.getDay()));
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    
    if (!dueAt) {
      return dueDateFilter.includes('no_due');
    }
    
    const dueDate = new Date(dueAt);
    
    if (dueDateFilter.includes('overdue') && dueDate < today) return true;
    if (dueDateFilter.includes('today') && dueDate >= today && dueDate < new Date(today.getTime() + 86400000)) return true;
    if (dueDateFilter.includes('this_week') && dueDate >= today && dueDate <= endOfWeek) return true;
    if (dueDateFilter.includes('this_month') && dueDate >= today && dueDate <= endOfMonth) return true;
    
    return false;
  };

  // 필터링된 태스크 (Work MVP 데이터만)
  const filteredTasks = useMemo(() => {
    let result = [...tasks];
    
    if (projectFilter.length > 0) {
      result = result.filter((t) => {
        if (t.projectId === null) {
          return projectFilter.includes('none');
        }
        return projectFilter.includes(t.projectId);
      });
    }
    
    if (dueDateFilter.length > 0) {
      result = result.filter((t) => matchesDueDateFilter(t.due_at));
    }
    
    return result;
  }, [tasks, projectFilter, dueDateFilter]);

  const filteredDoneTasks = useMemo(() => {
    let result = [...doneTasks];
    
    if (projectFilter.length > 0) {
      result = result.filter((t) => {
        if (t.projectId === null) {
          return projectFilter.includes('none');
        }
        return projectFilter.includes(t.projectId);
      });
    }
    
    return result;
  }, [doneTasks, projectFilter]);

  // 필터링된 투두
  const filteredTodos = useMemo(() => {
    let result = [...todos, ...scheduleTodoViews];
    
    if (dueDateFilter.length > 0) {
      result = result.filter((t) => matchesDueDateFilter(t.due_at));
    }
    
    return result;
  }, [todos, scheduleTodoViews, dueDateFilter]);

  const filteredDoneTodos = useMemo(() => {
    return [...doneTodos, ...scheduleDoneTodoViews];
  }, [doneTodos, scheduleDoneTodoViews]);

  const handleBack = () => {
    navigate(-1);
  };

  const handleSignOut = async () => {
    if (confirm('로그아웃 하시겠습니까?')) {
      await signOut();
    }
  };

  const handleTabChange = (tab: WorkTab) => {
    setActiveTab(tab);
    setSelectedProject(null);
    setSelectedTask(null);
    setSelectedTodo(null);
  };

  const handleViewModeToggle = () => {
    setViewMode(prev => prev === 'timeline' ? 'list' : 'timeline');
  };

  const handleSortModeToggle = () => {
    setSortMode(prev => prev === 'priority' ? 'time' : 'priority');
  };

  const handleShowCompletedToggle = () => {
    setShowCompleted(prev => !prev);
  };

  // Projects 탭 핸들러
  const handleOpenNewProjectModal = () => {
    setEditingProject(null);
    setIsProjectModalOpen(true);
  };

  const handleOpenEditProjectModal = (project: Project) => {
    setEditingProject(project);
    setSelectedProject(project);
    setIsProjectModalOpen(true);
  };

  const handleSaveProjectModal = async (projectData: Partial<Project>) => {
    if (editingProject && editingProject.id) {
      // 수정 (기존 프로젝트 - id가 있는 경우)
      const updated = { ...editingProject, ...projectData, updated_at: Date.now() } as Project;
      await updateProject(updated);
      setSelectedProject(updated);
    } else {
      // 새 프로젝트 (editingProject가 null이거나 id가 빈 문자열인 경우)
      const newProject = await createProject(projectData.title || '', projectData.color || '#a5b4fc');
      // 날짜 정보가 있으면 업데이트
      if (newProject && (projectData.start_at || projectData.end_at || projectData.due_at || projectData.description)) {
        // projectData에서 id 제외 (빈 문자열 id가 newProject.id를 덮어쓰는 것 방지)
        const { id: _, ...dataWithoutId } = projectData;
        await updateProject({
          ...newProject,
          ...dataWithoutId,
          updated_at: Date.now(),
        });
      }
    }
    setIsProjectModalOpen(false);
    setEditingProject(null);
  };

  const handleDeleteProject = async (projectId: string) => {
    await deleteProjectForever(projectId);
    setSelectedProject(null);
    setIsProjectModalOpen(false);
  };

  const handleCloseProjectModal = () => {
    setIsProjectModalOpen(false);
  };

  // 프로젝트 모달에서 태스크 추가
  const handleAddTaskFromProjectModal = async (title: string) => {
    if (editingProject) {
      await createTask(title, editingProject.id);
    }
  };

  // 프로젝트에서 태스크 클릭 시 태스크 모달 열기
  const handleTaskClickFromProjectModal = (task: ProjectTask) => {
    setEditingTask(task);
    setTaskModalProjectId(task.projectId);
    setIsTaskModalOpen(true);
  };

  // Tasks 탭 핸들러
  const handleOpenNewTaskModal = (projectId?: string | null) => {
    setEditingTask(null);
    setTaskModalProjectId(projectId || null);
    setIsTaskModalOpen(true);
  };

  const handleOpenEditTaskModal = (task: ProjectTask) => {
    setEditingTask(task);
    setSelectedTask(task);
    setTaskModalProjectId(task.projectId);
    setIsTaskModalOpen(true);
  };

  const handleSaveTaskModal = async (taskData: Partial<ProjectTask>) => {
    if (editingTask && editingTask.id) {
      // 수정 (기존 태스크 - id가 있는 경우)
      const updated = { ...editingTask, ...taskData, updated_at: Date.now() } as ProjectTask;
      await updateTask(updated);
      setSelectedTask(updated);
    } else {
      // 새 태스크 (editingTask가 null이거나 id가 빈 문자열인 경우)
      const newTask = await createTask(taskData.title || '', taskData.projectId || taskModalProjectId || null);
      // 날짜 정보가 있으면 업데이트
      if (newTask && (taskData.start_at || taskData.end_at || taskData.due_at || taskData.description)) {
        // taskData에서 id 제외 (빈 문자열 id가 newTask.id를 덮어쓰는 것 방지)
        const { id: _, ...dataWithoutId } = taskData;
        await updateTask({
          ...newTask,
          ...dataWithoutId,
          updated_at: Date.now(),
        });
      }
    }
    setIsTaskModalOpen(false);
    setEditingTask(null);
  };

  const handleCompleteTask = async (taskId: string) => {
    await completeTask(taskId);
    setSelectedTask(null);
  };

  const handleUndoCompleteTask = async (taskId: string) => {
    await undoCompleteTask(taskId);
  };

  const handleDeleteTask = async (taskId: string) => {
    await deleteTask(taskId);
    setSelectedTask(null);
    setIsTaskModalOpen(false);
  };

  const handleCloseTaskModal = () => {
    setIsTaskModalOpen(false);
  };

  // 태스크 모달에서 투두 추가
  const handleAddTodoFromTaskModal = async (content: string) => {
    if (editingTask) {
      await createTodo(content, editingTask.id);
    }
  };

  // 태스크 모달에서 투두 토글
  const handleToggleTodoFromTaskModal = async (todoId: string) => {
    const todo = todos.find(t => t.id === todoId) || doneTodos.find(t => t.id === todoId);
    if (todo) {
      if (todo.is_done) {
        await undoCompleteTodo(todoId);
      } else {
        await completeTodo(todoId);
      }
    }
  };

  // To do 탭 핸들러
  const handleOpenTodoModal = () => {
    setSelectedTodo(null);
    setTodoModalTaskId(null);
    setIsTodoModalOpen(true);
  };

  const handleSelectTodo = (todo: ProjectTodo) => {
    setSelectedTodo(todo);
    setIsTodoModalOpen(true);
  };

  const handleCloseTodoModal = () => {
    setSelectedTodo(null);
    setTodoModalTaskId(null);
    setIsTodoModalOpen(false);
  };

  const handleSaveTodoModal = async (todoData: Partial<ProjectTodo>) => {
    if (selectedTodo && selectedTodo.id) {
      // 기존 투두 수정 (id가 있는 경우)
      await updateTodo({ ...selectedTodo, ...todoData } as ProjectTodo);
    } else {
      // 새 투두 생성 (selectedTodo가 null이거나 id가 빈 문자열인 경우)
      await createTodo(
        todoData.content || '',
        todoData.taskId || todoModalTaskId,
        todoData.start_at || null,
        todoData.end_at || null,
        todoData.due_at || null,
        todoData.is_all_day ?? true,
        todoData.show_in_calendar ?? false
      );
    }
  };

  const handleCompleteTodo = async (todoId: string) => {
    await completeTodo(todoId);
    setSelectedTodo(null);
    setIsTodoModalOpen(false);
  };

  const handleUndoCompleteTodo = async (todoId: string) => {
    await undoCompleteTodo(todoId);
  };

  const handleDeleteTodo = async (todoId: string) => {
    await deleteTodo(todoId);
    setSelectedTodo(null);
    setIsTodoModalOpen(false);
  };

  // 일정 이벤트 핸들러
  const handleCloseEventModal = () => {
    setSelectedScheduleEvent(null);
    setIsEventModalOpen(false);
  };

  const handleSaveScheduleEvent = async (event: ScheduleEvent) => {
    await updateScheduleEvent(event);
    handleCloseEventModal();
  };

  const handleDeleteScheduleEvent = async (eventId: string) => {
    await deleteScheduleEvent(eventId);
    handleCloseEventModal();
  };

  // 정렬된 프로젝트 목록
  const sortedProjects = [...projects].sort((a, b) => {
    if (sortMode === 'priority') {
      return a.priority_order_index - b.priority_order_index;
    } else {
      const aTime = a.start_at ? new Date(a.start_at).getTime() : 
                    a.due_at ? new Date(a.due_at).getTime() : 
                    a.created_at;
      const bTime = b.start_at ? new Date(b.start_at).getTime() : 
                    b.due_at ? new Date(b.due_at).getTime() : 
                    b.created_at;
      return aTime - bTime;
    }
  });

  // 정렬된 태스크 목록
  const sortedTasks = [...tasks].sort((a, b) => {
    if (sortMode === 'priority') {
      return a.priority_order_index - b.priority_order_index;
    } else {
      const aTime = a.start_at ? new Date(a.start_at).getTime() : 
                    a.due_at ? new Date(a.due_at).getTime() : 
                    a.created_at;
      const bTime = b.start_at ? new Date(b.start_at).getTime() : 
                    b.due_at ? new Date(b.due_at).getTime() : 
                    b.created_at;
      return aTime - bTime;
    }
  });

  // 정렬된 투두 목록
  const sortedTodos = [...todos].sort((a, b) => {
    if (sortMode === 'priority') {
      return a.priority_order_index - b.priority_order_index;
    } else {
      const aTime = a.start_at ? new Date(a.start_at).getTime() : 
                    a.due_at ? new Date(a.due_at).getTime() : 
                    a.created_at;
      const bTime = b.start_at ? new Date(b.start_at).getTime() : 
                    b.due_at ? new Date(b.due_at).getTime() : 
                    b.created_at;
      return aTime - bTime;
    }
  });

  // 필터 적용된 태스크 (Work MVP 데이터만)
  const allTasks = useMemo(() => {
    if (projectFilter.length === 0 && dueDateFilter.length === 0) {
      return sortedTasks;
    }
    return filteredTasks;
  }, [sortedTasks, filteredTasks, projectFilter, dueDateFilter]);
  
  const allDoneTasks = useMemo(() => {
    if (projectFilter.length === 0) {
      return doneTasks;
    }
    return filteredDoneTasks;
  }, [doneTasks, filteredDoneTasks, projectFilter]);
  
  // 필터 적용된 통합 투두
  const allTodos = useMemo(() => {
    if (dueDateFilter.length === 0) {
      return [...sortedTodos, ...scheduleTodoViews];
    }
    return filteredTodos;
  }, [sortedTodos, scheduleTodoViews, filteredTodos, dueDateFilter]);
  
  const allDoneTodos = useMemo(() => {
    return filteredDoneTodos;
  }, [filteredDoneTodos]);

  // 현재 편집 패널 상태
  const hasEditPanel = selectedProject || selectedTask || selectedTodo;
  const isLoading = (activeTab === 'projects' && isLoadingProjects) || 
                    (activeTab === 'tasks' && (isLoadingTasks || isLoadingSchedule)) ||
                    (activeTab === 'todos' && (isLoadingTodos || isLoadingScheduleTodos));

  return (
    <div className="work-page">
      {/* 상단 헤더 */}
      <header className="work-header">
        <div className="header-left">
          <button 
            className="search-btn" 
            onClick={() => window.dispatchEvent(new Event('open-search'))}
            title="검색 (Ctrl+K)"
          >
            🔍
          </button>
        </div>
        <h1 className="work-title">작업</h1>
        <div className="header-right">
          <button className="schedule-btn" onClick={handleBack}>
            일정
          </button>
        </div>
      </header>

      {/* 탭 네비게이션 */}
      <nav className="work-tabs">
        <button 
          className={`tab-btn ${activeTab === 'projects' ? 'active' : ''}`}
          onClick={() => handleTabChange('projects')}
        >
          Projects
          {projects.length > 0 && (
            <span className="tab-count">{projects.length}</span>
          )}
        </button>
        <button 
          className={`tab-btn ${activeTab === 'tasks' ? 'active' : ''}`}
          onClick={() => handleTabChange('tasks')}
        >
          Tasks
          {tasks.length > 0 && (
            <span className="tab-count">{tasks.length}</span>
          )}
        </button>
        <button 
          className={`tab-btn ${activeTab === 'todos' ? 'active' : ''}`}
          onClick={() => handleTabChange('todos')}
        >
          To do
          {todos.length > 0 && (
            <span className="tab-count">{todos.length}</span>
          )}
        </button>
      </nav>

      {/* 툴바 */}
      <div className="work-toolbar">
        <div className="toolbar-left">
          {/* 뷰 모드 토글 */}
          <button 
            className={`toolbar-btn view-toggle ${viewMode}`}
            onClick={handleViewModeToggle}
          >
            {viewMode === 'timeline' ? '📅 Timeline' : '📋 List'}
          </button>

          {/* List 모드일 때만 정렬 토글 표시 */}
          {viewMode === 'list' && (
            <button 
              className={`toolbar-btn sort-toggle ${sortMode}`}
              onClick={handleSortModeToggle}
            >
              {sortMode === 'priority' ? '⭐ 중요도순' : '🕐 시간순'}
            </button>
          )}

          {/* 완료/아카이브 보기 토글 */}
          <button 
            className={`toolbar-btn completed-toggle ${showCompleted ? 'active' : ''}`}
            onClick={handleShowCompletedToggle}
          >
            {showCompleted ? '✓ 완료 표시' : '○ 완료 숨김'}
          </button>

          {/* Tasks/Todos 탭 필터 */}
          {(activeTab === 'tasks' || activeTab === 'todos') && (
            <>
              {activeTab === 'tasks' && projectFilterOptions.length > 1 && (
                <FilterDropdown
                  label="프로젝트"
                  options={projectFilterOptions}
                  selectedIds={projectFilter}
                  onChange={setProjectFilter}
                  showColorDot
                />
              )}
              <FilterDropdown
                label="마감일"
                options={DUE_DATE_OPTIONS}
                selectedIds={dueDateFilter}
                onChange={setDueDateFilter}
              />
            </>
          )}
        </div>

        <div className="toolbar-right">
          {/* 로딩 인디케이터 */}
          {isLoading && (
            <span className="loading-indicator">로딩중...</span>
          )}
        </div>
      </div>

      {/* 메인 컨텐츠 */}
      <main className={`work-content ${hasEditPanel ? 'with-panel' : ''}`}>
        <div className="content-main">
          {/* Projects 탭 */}
          {activeTab === 'projects' && viewMode === 'list' && (
            <ProjectList
              projects={sortedProjects}
              archivedProjects={archivedProjects}
              showArchived={showCompleted}
              onAddClick={handleOpenNewProjectModal}
              onSelectProject={handleOpenEditProjectModal}
              onReorderProjects={reorderProjects}
              onDeleteProject={deleteProjectForever}
              onArchiveProject={archiveProject}
              onUnarchiveProject={handleUnarchiveProject}
              selectedProjectId={selectedProject?.id}
            />
          )}
          {activeTab === 'projects' && viewMode === 'timeline' && (
            <ProjectsTimeline 
              items={showCompleted ? sortedProjects : sortedProjects.filter(p => p.status === 'ACTIVE')}
              projects={sortedProjects}
              scheduleEvents={scheduleEvents}
              onItemClick={(item) => handleOpenEditProjectModal(item as Project)}
              onScheduleEventClick={(event) => {
                setSelectedScheduleEvent(event);
                setIsEventModalOpen(true);
              }}
              onAddClick={(date) => {
                if (date) {
                  setEditingProject({
                    id: '',
                    userId: '',
                    title: '',
                    color: '#6366f1',
                    status: 'ACTIVE',
                    priority_order_index: 0,
                    created_at: Date.now(),
                    updated_at: Date.now(),
                    start_at: date.toISOString().split('T')[0],
                    end_at: null,
                    due_at: null,
                    archived_at: null,
                    is_all_day: true,
                  });
                  setIsProjectModalOpen(true);
                } else {
                  handleOpenNewProjectModal();
                }
              }}
            />
          )}

          {/* Tasks 탭 */}
          {activeTab === 'tasks' && viewMode === 'list' && (
            <TaskList
              tasks={allTasks}
              doneTasks={allDoneTasks}
              projects={projects}
              showCompleted={showCompleted}
              onAddClick={() => handleOpenNewTaskModal()}
              onSelectTask={handleOpenEditTaskModal}
              onCompleteTask={handleCompleteTask}
              onUndoComplete={handleUndoCompleteTask}
              onReorderTasks={reorderTasks}
              onDeleteTask={deleteTask}
              selectedTaskId={selectedTask?.id}
            />
          )}
          {activeTab === 'tasks' && viewMode === 'timeline' && (
            <TasksTimeline 
              items={showCompleted ? [...allTasks, ...allDoneTasks] : allTasks}
              projects={projects}
              scheduleEvents={scheduleEvents}
              onItemClick={(item) => handleOpenEditTaskModal(item as ProjectTask)}
              onScheduleEventClick={(event) => {
                setSelectedScheduleEvent(event);
                setIsEventModalOpen(true);
              }}
              onAddClick={(date) => {
                if (date) {
                  setEditingTask({
                    id: '',
                    projectId: null,
                    title: '',
                    status: 'ACTIVE',
                    priority_order_index: 0,
                    unscheduled_order_index: 0,
                    created_at: Date.now(),
                    updated_at: Date.now(),
                    start_at: date.toISOString().split('T')[0],
                    end_at: null,
                    due_at: null,
                    completed_at: null,
                    is_all_day: true,
                  });
                  setIsTaskModalOpen(true);
                } else {
                  handleOpenNewTaskModal();
                }
              }}
            />
          )}

          {/* To do 탭 */}
          {activeTab === 'todos' && viewMode === 'list' && (
            <TodoList
              todos={allTodos}
              doneTodos={allDoneTodos}
              tasks={tasks}
              projects={projects}
              showCompleted={showCompleted}
              onAddClick={handleOpenTodoModal}
              onSelectTodo={handleSelectTodo}
              onCompleteTodo={handleCompleteTodo}
              onUndoComplete={handleUndoCompleteTodo}
              onReorderTodos={reorderTodos}
              onDeleteScheduleTodo={deleteScheduleTodo}
              onDeleteTodo={deleteTodo}
              selectedTodoId={selectedTodo?.id}
            />
          )}
          {activeTab === 'todos' && viewMode === 'timeline' && (
            <TodosTimeline 
              items={showCompleted ? [...allTodos, ...allDoneTodos] : allTodos}
              tasks={tasks}
              projects={projects}
              scheduleEvents={scheduleEvents}
              onItemClick={(item) => handleSelectTodo(item as ProjectTodo)}
              onScheduleEventClick={(event) => {
                setSelectedScheduleEvent(event);
                setIsEventModalOpen(true);
              }}
              onAddClick={(date) => {
                if (date) {
                  setSelectedTodo({
                    id: '',
                    taskId: null,
                    content: '',
                    is_done: false,
                    completed_at: null,
                    priority_order_index: 0,
                    unscheduled_order_index: 0,
                    created_at: Date.now(),
                    updated_at: Date.now(),
                    start_at: date.toISOString().split('T')[0],
                    end_at: null,
                    due_at: null,
                    is_all_day: true,
                    show_in_calendar: false,
                  });
                  setIsTodoModalOpen(true);
                } else {
                  handleOpenTodoModal();
                }
              }}
            />
          )}
        </div>

      </main>

      {/* 프로젝트 모달 */}
      <ProjectModal
        project={editingProject}
        isOpen={isProjectModalOpen}
        tasks={editingProject ? tasks.filter(t => t.projectId === editingProject.id) : []}
        onClose={handleCloseProjectModal}
        onSave={handleSaveProjectModal}
        onDelete={handleDeleteProject}
        onTaskClick={handleTaskClickFromProjectModal}
        onAddTask={handleAddTaskFromProjectModal}
      />

      {/* 태스크 모달 */}
      <TaskModal
        task={editingTask}
        isOpen={isTaskModalOpen}
        projects={projects}
        todos={editingTask ? [...todos, ...doneTodos].filter(t => t.taskId === editingTask.id) : []}
        defaultProjectId={taskModalProjectId}
        onClose={handleCloseTaskModal}
        onSave={handleSaveTaskModal}
        onDelete={handleDeleteTask}
        onAddTodo={handleAddTodoFromTaskModal}
        onToggleTodo={handleToggleTodoFromTaskModal}
        onTodoClick={handleSelectTodo}
      />

      {/* To do 모달 */}
      <TodoModal
        todo={selectedTodo}
        isOpen={isTodoModalOpen}
        tasks={tasks}
        projects={projects}
        defaultTaskId={todoModalTaskId}
        onClose={handleCloseTodoModal}
        onSave={handleSaveTodoModal}
        onDelete={handleDeleteTodo}
      />

      {/* 일정 이벤트 모달 */}
      <EventModal
        event={selectedScheduleEvent}
        isOpen={isEventModalOpen}
        onClose={handleCloseEventModal}
        onSave={handleSaveScheduleEvent}
        onDelete={handleDeleteScheduleEvent}
      />

      {/* 하단 푸터 */}
      <footer className="work-footer">
        <button className="logout-btn" onClick={handleSignOut} title={user?.email || ''}>
          로그아웃
        </button>
      </footer>
    </div>
  );
}
